static String recommendConflictStrategy(boolean exact, boolean audit, boolean unwanted) {
    if (exact) return "force";
    if (audit) return "failOnVersionConflict";
    if (unwanted) return "exclude";
    return "domyslna strategia (najnowsza wygrywa)";
}
