static List<String> extractVersionNames(String toml) {
    List<String> names = new ArrayList<>();
    boolean inVersions = false;
    for (String line : toml.split("\n")) {
        line = line.trim();
        if (line.equals("[versions]")) { inVersions = true; continue; }
        if (line.startsWith("[")) { inVersions = false; continue; }
        if (inVersions && line.contains("=")) names.add(line.split("=")[0].trim());
    }
    return names;
}

