static String generateVersionCatalog(Map<String,String> versions, Map<String,String> libToVersionKey) {
    StringBuilder sb = new StringBuilder("[versions]\n");
    versions.forEach((k,v) -> sb.append(k).append("='").append(v).append("'\n"));
    sb.append("[libraries]\n");
    libToVersionKey.forEach((lib,vk) -> sb.append(lib).append("={module='...:").append(lib).append("',version.ref='").append(vk).append("'}\n"));
    return sb.toString();
}

