record SubstitutionRule(String from, String to) {}
static List<String> applySubstitutionRules(List<String> deps, List<SubstitutionRule> rules) {
    List<String> result = new ArrayList<>();
    for (String d : deps) {
        String out = d;
        for (SubstitutionRule r : rules) if (r.from().equals(d)) out = r.to();
        result.add(out);
    }
    return result;
}

static void detectCatalogDrift(Map<String,String> before, Map<String,String> after) {
    for (String k : after.keySet()) if (!before.containsKey(k)) System.out.println("DODANE: " + k);
    for (String k : before.keySet()) if (!after.containsKey(k)) System.out.println("USUNIETE: " + k);
    for (String k : before.keySet()) if (after.containsKey(k) && !before.get(k).equals(after.get(k))) System.out.println("ZMIENIONE: " + k);
}

