static String migrateToVersionCatalog(String old) {
    StringBuilder toml = new StringBuilder("[versions]\n");
    Pattern p = Pattern.compile("'([^:]+):([^:]+):([^']+)'");
    Matcher m = p.matcher(old);
    while (m.find()) toml.append(m.group(2)).append("='").append(m.group(3)).append("'\n");
    return toml.toString();
}

